export function TouchJoystick({ label, size = DEFAULT_SIZE, deadzone = DEFAULT_DEADZONE, onChange, disabled = false }: TouchJoystickProps) {
  const reducedMotion = useReducedMotion();
  const baseRef = React.useRef<HTMLDivElement>(null);
  const activeRef = React.useRef(false);
  const centerRef = React.useRef({ x: 0, y: 0 });
  const [knob, setKnob] = React.useState({ x: 0, y: 0 }); // px offset from center
  const radius = size / 2;

  const emit = (dx: number, dy: number) => {
    const v = joystickVector(dx, dy, radius, deadzone);
    onChange(v);
    setKnob(clampToRadius(dx, dy, radius));
  };

  const handleDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (disabled) return;
    const el = e.currentTarget;
    const rect = el.getBoundingClientRect();
    centerRef.current = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
    el.setPointerCapture(e.pointerId);
    activeRef.current = true;
    emit(e.clientX - centerRef.current.x, centerRef.current.y - e.clientY);
  };

  const handleMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!activeRef.current) return;
    emit(e.clientX - centerRef.current.x, centerRef.current.y - e.clientY);
  };

  const end = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!activeRef.current) return;
    activeRef.current = false;
    const el = e.currentTarget;
    if (el.hasPointerCapture(e.pointerId)) el.releasePointerCapture(e.pointerId);
    setKnob({ x: 0, y: 0 });
    onChange({ x: 0, y: 0 });
  };
